<script setup lang="ts">import {onMounted,ref} from 'vue';import {request} from '../../api/http';const items=ref<any[]>([]),error=ref('');onMounted(async()=>{try{items.value=(await request<any>({url:'/public/campuses'})).data;}catch{error.value='加载失败';}});</script><template><view class="page"><view v-if="error">{{error}}</view><view v-else-if="!items.length">暂无已发布院区</view><view v-for="item in items" :key="item.id" class="card"><text class="name">{{item.name}}</text><text>{{item.address||'地址待完善'}}</text><text>{{item.transportation}}</text></view></view></template><style scoped>.page{padding:28rpx}.card{display:flex;flex-direction:column;gap:12rpx;padding:28rpx;background:#fff;border-radius:16rpx;margin-bottom:18rpx;color:#64748b}.name{font-size:34rpx;color:#17324d;font-weight:700}</style>
